    expiration: Str? = None,
    // Provides information about object restoration action and expiration time
    // of the restored object copy.
    restore: Str? = None,
    // Date and time when the object was last modified.
    last_modified: Instant? = None,
    // Size of the body in bytes.
    content_length: Long? = None,
    // An entity tag (ETag) is an opaque identifier assigned by a web server to
    // a specific version of a resource found at a URL.
    e_tag: Str? = None,
    // The Base64 encoded, 32-bit CRC32 checksum of the object. This checksum is
    // only present if the checksum was uploaded with the object. For more
    // information, see Checking object integrity in the Amazon S3 User Guide.
