    // to create an object-level checksum for multipart objects. You can use
    // this header response to verify that the checksum type that is received is
    // the same checksum type that was specified in the CreateMultipartUpload
    // request. For more information, see Checking object integrity in the
    // Amazon S3 User Guide.
    checksum_type: ChecksumType? = None,
    // This is set to the number of metadata entries not returned in the headers
